var fixed = `desc:Telephone AutoPan
tags: utility modulation filter
in_pin:Input L
in_pin:Input R
out_pin:Output L
out_pin:Output R

slider1:center_freq=1700<300,4000,1>Bandpass Center Frequency (Hz)
slider2:band_width=1000<200,3000,1>Bandpass Width (Hz)
slider3:pan_rate=1.8<0.1,8,0.01>Autopan Rate (Hz)
slider4:pan_depth=0.80<0,1,0.01>Autopan Depth
slider5:wet_mix=1.0<0,1,0.01>Wet Mix

@init
two_pi = 2*$pi;
phase = 0;

// HP biquad state
hp_x1L = hp_x2L = hp_y1L = hp_y2L = 0;
hp_x1R = hp_x2R = hp_y1R = hp_y2R = 0;

// LP biquad state
lp_x1L = lp_x2L = lp_y1L = lp_y2L = 0;
lp_x1R = lp_x2R = lp_y1R = lp_y2R = 0;

@slider
// Intention:
// 1) derive low_cut and high_cut from the center frequency and the width
// 2) clamp low_cut / high_cut properly
// 3) build one 2nd-order RBJ high-pass and one 2nd-order RBJ low-pass
//    so that cascading them gives a telephone-style bandpass
low_cut  = center_freq - band_width * 0.5;
high_cut = center_freq + band_width * 0.5;

// clamp low_cut / high_cut properly
nyq = srate * 0.5;
low_cut  = min(max(low_cut, 20), nyq * 0.98);
high_cut = min(max(high_cut, low_cut + 10), nyq * 0.98);

// --- high-pass biquad ---
w0_hp = two_pi * low_cut / srate;
cos_hp = cos(w0_hp);
sin_hp = sin(w0_hp);

// Butterworth (maximally flat) Q for a single 2nd-order section
Q_hp = sqrt(2) * 0.5;
alpha_hp = sin_hp / (2 * Q_hp);

// RBJ high-pass coefficients
hp_b0 =  (1 + cos_hp) * 0.5;
hp_b1 = -(1 + cos_hp);
hp_b2 =  (1 + cos_hp) * 0.5;
hp_a0 =  1 + alpha_hp;
hp_a1 = -2 * cos_hp;
hp_a2 =  1 - alpha_hp;

// normalize
hp_b0 /= hp_a0;
hp_b1 /= hp_a0;
hp_b2 /= hp_a0;
hp_a1 /= hp_a0;
hp_a2 /= hp_a0;

// --- low-pass biquad ---
w0_lp = two_pi * high_cut / srate;
cos_lp = cos(w0_lp);
sin_lp = sin(w0_lp);

// same Butterworth Q as the high-pass section
Q_lp = sqrt(2) * 0.5;
alpha_lp = sin_lp / (2 * Q_lp);

// RBJ low-pass coefficients
lp_b0 = (1 - cos_lp) * 0.5;
lp_b1 =  1 - cos_lp;
lp_b2 = (1 - cos_lp) * 0.5;
lp_a0 =  1 + alpha_lp;
lp_a1 = -2 * cos_lp;
lp_a2 =  1 - alpha_lp;

// normalize
lp_b0 /= lp_a0;
lp_b1 /= lp_a0;
lp_b2 /= lp_a0;
lp_a1 /= lp_a0;
lp_a2 /= lp_a0;

// --- autopan LFO phase increment, per sample ---
phase_inc = two_pi * pan_rate / srate;

@sample
dryL = spl0;
dryR = spl1;

// ---------- high-pass stage ----------
// Left
hp_outL =
    hp_b0 * dryL +
    hp_b1 * hp_x1L +
    hp_b2 * hp_x2L -
    hp_a1 * hp_y1L -
    hp_a2 * hp_y2L;

// Right
hp_outR =
    hp_b0 * dryR +
    hp_b1 * hp_x1R +
    hp_b2 * hp_x2R -
    hp_a1 * hp_y1R -
    hp_a2 * hp_y2R;

// update HP state for both channels
hp_x2L = hp_x1L;
hp_x1L = dryL;
hp_y2L = hp_y1L;
hp_y1L = hp_outL;

hp_x2R = hp_x1R;
hp_x1R = dryR;
hp_y2R = hp_y1R;
hp_y1R = hp_outR;

// ---------- low-pass stage ----------
lp_outL =
    lp_b0 * hp_outL +
    lp_b1 * lp_x1L +
    lp_b2 * lp_x2L -
    lp_a1 * lp_y1L -
    lp_a2 * lp_y2L;

lp_outR =
    lp_b0 * hp_outR +
    lp_b1 * lp_x1R +
    lp_b2 * lp_x2R -
    lp_a1 * lp_y1R -
    lp_a2 * lp_y2R;

// update LP state for both channels
lp_x2L = lp_x1L;
lp_x1L = hp_outL;
lp_y2L = lp_y1L;
lp_y1L = lp_outL;

lp_x2R = lp_x1R;
lp_x1R = hp_outR;
lp_y2R = lp_y1R;
lp_y1R = lp_outR;

// ---------- stereo autopan ----------
// sinusoidal LFO; left and right gains move in opposite directions,
// and with pan_depth = 0 both gains stay at 1 (no panning motion)
lfo = sin(phase);
gainL = 1 - pan_depth * 0.5 * (1 + lfo);
gainR = 1 - pan_depth * 0.5 * (1 - lfo);

procL = lp_outL * gainL;
procR = lp_outR * gainR;

// ---------- wet / dry mix ----------
// wet_mix = 0 -> fully dry, wet_mix = 1 -> fully processed
outL = wet_mix * procL + (1 - wet_mix) * dryL;
outR = wet_mix * procR + (1 - wet_mix) * dryR;

spl0 = outL;
spl1 = outR;

// advance and wrap phase
phase += phase_inc;
phase >= two_pi ? phase -= two_pi;
`;
